    42	 * Small text preview helper.
    43	 */
    44	function preview_text(string $html, int $length = 280): string
    45	{
    46	  $plain = trim(strip_tags($html));
    47	  $plain = preg_replace('/\s+/', ' ', $plain) ?? $plain;
    48	  $strlen = function_exists('mb_strlen') ? (int) mb_strlen($plain) : strlen($plain);
    49	  if ($strlen <= $length) {
    50	    return $plain;
    51	  }
    52	  $slice = function_exists('mb_substr') ? (string) mb_substr($plain, 0, $length) : substr($plain, 0, $length);
    53	  return $slice . '...';
    54	}
